{"script":"targets = ["src/a.txt", "src/nested/b.txt"]
for p in targets:
    repo.edit(p, "legacy_flag", "modern_flag", all = True)

docs_before = repo.read("docs/history.txt")
untouched_before = repo.read("src/untouched.txt")

# verify
after = {}
for p in targets + ["src/untouched.txt", "docs/history.txt"]:
    after[p] = repo.read(p)

res = repo.search("legacy_flag", glob = "**")
return {
    "after": after,
    "remaining_legacy_flag_hits": [{"path": h.path, "line": h.line, "text": h.text} for h in res],
    "docs_unchanged": docs_before == after["docs/history.txt"],
    "untouched_unchanged": untouched_before == after["src/untouched.txt"],
    "status": repo.status(),
    "diff": repo.diff(),
}"}
